cat > /workspace/brute.c <<'C'
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
static uint32_t K[4];
uint32_t expand(uint32_t k){return k ^ (k<<16) ^ (k*12345);}
uint8_t g(uint8_t a,uint8_t b,uint8_t x){uint8_t t=(a+b+x)&0xFF;return ((t<<2)|(t>>6))&0xFF;}
uint32_t f(uint32_t v){uint8_t x[4],y[4];for(int i=0;i<4;i++){x[i]=v&0xFF;v>>=8;}y[2]=g(x[3]^x[2],x[1]^x[0],1);y[3]=g(x[3],y[2],0);y[1]=g(x[1]^x[0],y[2],0);y[0]=g(x[0],y[1],1);uint32_t o=0;for(int i=0;i<4;i++)o|=(uint32_t)y[i]<<(8*i);return o;}
uint64_t enc(uint64_t p){uint32_t l=p>>32,r=p&0xFFFFFFFF;r^=l;for(int i=0;i<4;i++){uint32_t m=f(r^K[i]);uint32_t t=r;r=l^m;l=t;}l^=r;return ((uint64_t)r<<32)|l;}
uint64_t P[32],C[32];
int main(){
 FILE*fp=fopen("/workspace/pairs.txt","r");
 for(int i=0;i<32;i++)fscanf(fp,"%lu %lu",&P[i],&C[i]);fclose(fp);
 for(uint32_t s=0;s<(1u<<20);s++){
   uint32_t e=expand(s); for(int j=0;j<4;j++)K[j]=e;
   int ok=1; for(int i=0;i<32;i++){if(enc(P[i])!=C[i]){ok=0;break;}}
   if(ok){printf("FOUND all equal seed=%x\n",s);return 0;}
 }
 printf("not all equal\n");
 return 1;
}
C
