int main(){uint32_t s[4]={0x68e63,0x62571,0x1f61c,0xb74a5};for(int i=0;i<4;i++)K[i]=expand(s[i]);FILE*fp=fopen("pairs.txt","r");int i=0,bad=0;unsigned long p,c;while(fscanf(fp,"%lu %lu",&p,&c)==2){if(enc(p)!=c){printf("BAD %d\n",i);bad=1;}i++;}printf("checked %d pairs, bad=%d\n",i,bad);return 0;}
